 11→func TestLoad_RejectsUnknownKeys(t *testing.T) {
 12→	// Create a temporary directory
 13→	tmpDir := t.TempDir()
 14→
 15→	// Create .entire directory
 16→	entireDir := filepath.Join(tmpDir, ".entire")
 17→	if err := os.MkdirAll(entireDir, 0755); err != nil {
 18→		t.Fatalf("failed to create .entire directory: %v", err)
 19→	}
 20→
 21→	// Create settings.json with an unknown key
 22→	settingsFile := filepath.Join(entireDir, "settings.json")
 23→	settingsContent := `{"enabled": true, "unknown_key": "value"}`
 24→	if err := os.WriteFile(settingsFile, []byte(settingsContent), 0644); err != nil {
 25→		t.Fatalf("failed to write settings file: %v", err)
 26→	}
 27→
 28→	// Initialize a git repo (required by paths.AbsPath)
 29→	if err := os.MkdirAll(filepath.Join(tmpDir, ".git"), 0755); err != nil {
 30→		t.Fatalf("failed to create .git directory: %v", err)
 31→	}
 32→
 33→	// Change to the temp directory
 34→	t.Chdir(tmpDir)
 35→
 36→	// Try to load settings - should fail due to unknown key
 37→	_, err := Load(context.Background())
 38→	if err == nil {
 39→		t.Error("expected error for unknown key, got nil")
 40→	} else if !containsUnknownField(err.Error()) {
 41→		t.Errorf("expected unknown field error, got: %v", err)
 42→	}
 43→}
 44→
 45→func TestLoad_AcceptsValidKeys(t *testing.T) {
 46→	// Create a temporary directory
 47→	tmpDir := t.TempDir()
 48→
 49→	// Create .entire directory
 50→	entireDir := filepath.Join(tmpDir, ".entire")
 51→	if err := os.MkdirAll(entireDir, 0755); err != nil {
 52→		t.Fatalf("failed to create .entire directory: %v", err)
 53→	}
 54→
 55→	// Create settings.json with all valid keys
 56→	settingsFile := filepath.Join(entireDir, "settings.json")
 57→	settingsContent := `{
 58→		"enabled": true,
 59→		"local_dev": false,
 60→		"log_level": "debug",
 61→		"strategy_options": {"key": "value"},
 62→		"telemetry": true,
 63→		"external_agents": true
 64→	}`
 65→	if err := os.WriteFile(settingsFile, []byte(settingsContent), 0644); err != nil {
 66→		t.Fatalf("failed to write settings file: %v", err)
 67→	}
 68→
 69→	// Initialize a git repo (required by paths.AbsPath)
 70→	if err := os.MkdirAll(filepath.Join(tmpDir, ".git"), 0755); err != nil {
 71→		t.Fatalf("failed to create .git directory: %v", err)
 72→	}
 73→
 74→	// Change to the temp directory
 75→	t.Chdir(tmpDir)
 76→
 77→	// Load settings - should succeed
 78→	settings, err := Load(context.Background())
 79→	if err != nil {
 80→		t.Fatalf("unexpected error: %v", err)
 81→	}
 82→
 83→	// Verify values
 84→	if !settings.Enabled {
 85→		t.Error("expected enabled to be true")
 86→	}
 87→	if settings.LogLevel != "debug" {
 88→		t.Errorf("expected log_level 'debug', got %q", settings.LogLevel)
 89→	}
 90→	if settings.Telemetry == nil || !*settings.Telemetry {
 91→		t.Error("expected telemetry to be true")
 92→	}
 93→}
