func TestInstallGitHook_NoBackupWhenNoExistingHook(t *testing.T) {
	_, hooksDir := initHooksTestRepo(t)

	_, err := InstallGitHook(context.Background(), true, false, false)
	if err != nil {
		t.Fatalf("InstallGitHook() error = %v", err)
